  "index.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"description\" content=\"MV Face Recognition - AI-powered video face detection and recognition system\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>Face Recognition Dashboard</title>\n    <link rel=\"icon\" href=\"/favicon.png\" />\n    \n\t\t<link rel=\"modulepreload\" href=\"/_app/immutable/entry/start.SQs-hfE8.js\">\n\t\t<link rel=\"modulepreload\" href=\"/_app/immutable/chunks/DMfC9y8m.js\">\n\t\t<link rel=\"modulepreload\" href=\"/_app/immutable/chunks/Bj-HysMQ.js\">\n\t\t<link rel=\"modulepreload\" href=\"/_app/immutable/entry/app.Beb27lWB.js\">\n\t\t<link rel=\"modulepreload\" href=\"/_app/immutable/chunks/DsnmJJEf.js\">\n    <style>\n        :root {\n            /* Color Palette */\n            --primary-color: #2563eb;\n            --primary-hover: #1d4ed8;\n            --secondary-color: #64748b;\n            --success-color: #22c55e;\n            --warning-color: #eab308;\n            --error-color: #ef4444;\n            --info-color: #3b82f6;\n\n            /* Surface Colors */\n            --bg-color: #ffffff;\n            --surface-color: #f8fafc;\n            --border-color: #e2e8f0;\n            --text-color: #1e293b;\n            --text-secondary: #64748b;\n            --text-muted: #94a3b8;\n\n            /* Dark mode */\n            --dark-bg-color: #0f172a;\n            --dark-surface-color: #1e293b;\n            --dark-border-color: #334155;\n            --dark-text-color: #f1f5f9;\n            --dark-text-secondary: #94a3b8;\n\n            /* Shadows */\n            --shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1);\n            --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);\n\n            /* Transitions */\n            --transition: all 0.2s ease;\n        }\n\n        [data-theme=\"dark\"] {\n            --bg-color: var(--dark-bg-color);\n            --surface-color: var(--dark-surface-color);\n            --border-color: var(--dark-border-color);\n            --text-color: var(--dark-text-color);\n            --text-secondary: var(--dark-text-secondary);\n        }\n\n        * {\n            box-sizing: border-box;\n            margin: 0;\n            padding: 0;\n        }\n\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\n            background-color: var(--bg-color);\n            color: var(--text-color);\n            line-height: 1.6;\n            transition: var(--transition);\n        }\n\n        /* Face Recognition Dashboard Specific Styles */\n        .dashboard-layout {\n            min-height: 100vh;\n            background-color: #1a1a1a;\n            color: #ffffff;\n            display: flex;\n            flex-direction: column;\n        }\n\n        .header-bar {\n            height: 60px;\n            background-color: #2a2a2a;\n            display: flex;\n            align-items: center;\n            justify-content: space-between;\n            padding: 0 20px;\n            border-bottom: 1px solid #444;\n        }\n\n        .app-title {\n            font-size: 20px;\n            font-weight: 600;\n            color: #ffffff;\n        }\n\n        .status-indicator {\n            background-color: #22c55e;\n            color: #000;\n            padding: 6px 12px;\n            border-radius: 4px;\n            font-weight: 600;\n            font-size: 12px;\n            animation: pulse 2s infinite;\n        }\n\n        @keyframes pulse {\n            0%, 100% { opacity: 1; }\n            50% { opacity: 0.7; }\n        }\n\n        .main-content {\n            flex: 1;\n            display: flex;\n            min-height: calc(100vh - 260px);\n        }\n\n        .video-panel {\n            width: 60%;\n            background-color: #000000;\n            position: relative;\n            border-right: 1px solid #444;\n        }\n\n        .face-panel {\n            width: 40%;\n            background-color: #1e293b;\n            padding: 20px;\n            overflow-y: auto;\n        }\n\n        .similarity-panel {\n            height: 200px;\n            background-color: #374151;\n            padding: 20px;\n            border-top: 1px solid #444;\n        }\n    </style>\n</head>\n<body data-sveltekit-preload-data=\"hover\">\n    <div style=\"display: contents\">\n\t\t\t<script>\n\t\t\t\t{\n\t\t\t\t\t__sveltekit_lkcak1 = {\n\t\t\t\t\t\tbase: \"\"\n\t\t\t\t\t};\n\n\t\t\t\t\tconst element = document.currentScript.parentElement;\n\n\t\t\t\t\tPromise.all([\n\t\t\t\t\t\timport(\"/_app/immutable/entry/start.SQs-hfE8.js\"),\n\t\t\t\t\t\timport(\"/_app/immutable/entry/app.Beb27lWB.js\")\n\t\t\t\t\t]).then(([kit, app]) => {\n\t\t\t\t\t\tkit.start(app, element);\n\t\t\t\t\t});\n\t\t\t\t}\n\t\t\t</script>\n\t\t</div>\n</body>\n</html>"
